package main

import (
	"fmt"
	"time"
)

func main() {
	// 当前时间、格式化与时间戳
	now := time.Now()
	fmt.Println("现在:", now.Format(time.RFC3339))
	fmt.Println("时间戳(毫秒):", now.UnixMilli())

	// 时区
	zone, offset := now.Zone()
	fmt.Println("时区:", zone, "偏移小时:", offset/3600)
	fmt.Println("本地时间:", now.In(time.Local).Format("2006-01-02 15:04:05"))

	// 加减、时间差与比较
	deadline := now.Add(30 * time.Minute)
	fmt.Println("半小时后:", deadline.Format("2006-01-02 15:04:05"))
	fmt.Println("相差分钟:", deadline.Sub(now).Minutes())
	fmt.Println("已超时?", now.After(deadline))

	// 解析时间字符串与时长字符串
	parsed, err := time.Parse(time.RFC3339, "2026-10-29T16:45:38+08:00")
	if err != nil {
		fmt.Println("解析失败:", err)
		return
	}
	fmt.Println("解析得到:", parsed.Format("2006-01-02 15:04:05"))

	d, err := time.ParseDuration("1h30m")
	if err != nil {
		fmt.Println("时长解析失败:", err)
		return
	}
	fmt.Println("时长:", d)

	// 定时器: 延时回调与超时等待
	start := time.Now()
	timer := time.AfterFunc(200*time.Millisecond, func() {
		fmt.Println("AfterFunc 回调触发")
	})
	time.Sleep(300 * time.Millisecond)
	fmt.Println("定时器已触发, Stop 返回:", timer.Stop())

	select {
	case <-time.After(50 * time.Millisecond):
		fmt.Println("等待结束")
	case <-time.After(2 * time.Second):
		fmt.Println("超时")
	}

	idle := time.NewTimer(time.Hour)
	fmt.Println("取消长定时器:", idle.Stop())
	fmt.Println("总耗时:", time.Now().Sub(start))
}
